<?php
declare(strict_types=1);
require_once __DIR__.'/../core/integrations/staffing_workbook.php';
require_once __DIR__.'/fixtures/staffing_workbook_fixture.php';
$passed=0;$check=static function(bool $ok,string $label)use(&$passed):void{if(!$ok)throw new RuntimeException($label);$passed++;echo "PASS $label\n";};
$fails=static function(callable $fn):bool{try{$fn();return false;}catch(InvalidArgumentException $e){return true;}};
[$bytes,$selection]=staffingWorkbookFixture();$read=static fn(array $replace=[],array $extra=[])=>staffingWorkbookRead(staffingWorkbookFixture($replace,$extra)[0],'synthetic.xlsx',$selection);
$source=staffingWorkbookRead($bytes,'synthetic.xlsx',$selection);
$check($source['period']===['start'=>'2026-10-01','end'=>'2026-10-31']&&count($source['days'])===31,'actual month cell and complete day headers establish the worksheet period');
$check($source['numeric_hours_sum']==='16.00'&&$source['stated_hours']==='16.00'&&$source['hours_difference']==='0.00','known numeric inputs independently sum to the saved total');
$check($source['days'][2]['hours']==='0.00'&&$source['days'][3]['hours']===null&&$source['blank_days']===28&&!$source['blank_means_zero'],'explicit zeros and blank days remain distinct');
$check($source['calculated_bill_amount']==='1568.00'&&$source['bill_amount_difference']==='0.00'&&$source['currency']===null,'hour-rate arithmetic does not invent an ISO currency');
$check($source['cells']['A6']['formula']==='SUM(C5:AG5)'&&$source['calculation_basis']==='stored_cell_values_not_recalculated','original formula and cached-value basis remain visible');
$check($source['file_sha256']===hash('sha256',$bytes)&&$source['file_bytes']===strlen($bytes),'source fingerprint belongs to the exact workbook bytes');
$check(!$source['original_client_approval_proven']&&!$source['provider_dates_changed']&&!$source['time_entries_matched']&&!$source['cash_delivery_proven'],'worksheet agreement establishes no approval or external authority');
$check(staffingWorkbookRead($bytes,'synthetic.xlsx',array_replace($selection,['currency_cell'=>'A9']))['currency']==='USD','an explicitly selected currency cell is retained');
$check($read(['<f>SUM(C5:AG5)</f><v>16</v>'=>'<f>SUM(C5:AG5)</f><v>15</v>'])['hours_difference']==='-1.00','stale or different worksheet total is an explicit difference');
$check($read(['<v>1568</v>'=>'<v>1600</v>'])['bill_amount_difference']==='32.00','different cached amount is not forced to match');
$check($fails(fn()=>staffingWorkbookRead($bytes,'../synthetic.xlsx',$selection)),'filesystem names are not accepted as upload names');
$check($fails(fn()=>staffingWorkbookRead($bytes,'synthetic.xlsm',$selection)),'macro-enabled extension is refused');
$check($fails(fn()=>staffingWorkbookRead('not a workbook','synthetic.xlsx',$selection)),'non-workbook bytes are refused');
$check($fails(fn()=>staffingWorkbookParts('PK'."\x03\x04".str_repeat('x',STAFFING_WORKBOOK_MAX_BYTES))),'oversized source bytes are refused before parsing');
$check($fails(fn()=>staffingWorkbookRead($bytes,'synthetic.xlsx',array_replace($selection,['sheet'=>'Missing']))),'worksheet selection is exact');
$check($fails(fn()=>staffingWorkbookRead($bytes,'synthetic.xlsx',array_replace($selection,['day_header_range'=>'C4:AF4']))),'partial-month header selection cannot assert a complete month');
$check($fails(fn()=>staffingWorkbookRead($bytes,'synthetic.xlsx',array_replace($selection,['hours_range'=>'C5:AG6']))),'multi-row ranges are refused');
$check($fails(fn()=>staffingWorkbookCellAddress('XFE1'))&&$fails(fn()=>staffingWorkbookCellAddress('A1048577')),'out-of-worksheet source addresses are refused');
$check($fails(fn()=>$read(['<v>2026-10-01T00:00:00</v>'=>'<v>2026-10-02T00:00:00</v>'])),'a non-month-start date is not silently rounded');
$check($fails(fn()=>$read(['<c r="A1" t="d"><v>2026-10-01T00:00:00</v></c>'=>'<c r="A1" t="inlineStr"><is><t>Oct 2026</t></is></c>'])),'a period label is not promoted to an actual source date');
$check($fails(fn()=>$read(['<c r="D4"><v>2</v></c>'=>'<c r="D4"><v>1</v></c>'])),'duplicate day headers are refused');
$check($fails(fn()=>$read(['<c r="C5"><v>8</v></c>'=>'<c r="C5" t="str"><v>8</v></c>'])),'numeric-looking text is not silently converted');
$check($fails(fn()=>$read(['<c r="C5"><v>8</v></c>'=>'<c r="C5"><v>-8</v></c>'])),'negative daily hours require correction');
$check($fails(fn()=>$read(['<c r="C5"><v>8</v></c>'=>'<c r="C5"><v>25</v></c>'])),'over-24-hour daily values require correction');
$check($fails(fn()=>$read(['<f>SUM(C5:AG5)</f><v>16</v>'=>'<f>SUM(C5:AG5)</f>'])),'formula without a cached result is refused');
$check($fails(fn()=>$read(['<c r="C5"><v>8</v></c>'=>'<c r="C5"><v>8</v></c><c r="C5"><v>7</v></c>'])),'duplicate selected cells are refused');
$check($fails(fn()=>$read([],['../outside.xml'=>'<x/>'])),'archive traversal paths are refused without extraction');
$check($fails(fn()=>$read([],['xl/vbaProject.bin'=>'synthetic'])),'embedded macros are refused');
$check($fails(fn()=>$read([],['xl/workbook.xml'=>'<!DOCTYPE workbook [<!ENTITY external SYSTEM "file:///etc/passwd">]><workbook>&external;</workbook>'])),'XML entities are refused before parsing');
$check(staffingWorkbookMonth(['type'=>'n','value'=>'61'],'1900')==='1900-03-01','Excel 1900 leap-day discontinuity is handled');
$check($fails(fn()=>staffingWorkbookMonth(['type'=>'n','value'=>'60'],'1900')),'Excel fictitious leap day is never accepted');
$check(staffingWorkbookMonth(['type'=>'n','value'=>'0'],'1904')==='1904-01-01','Excel 1904 date system is explicit');
$check($fails(fn()=>staffingWorkbookXml(implode("\0",str_split('<!DOCTYPE workbook><workbook/>')))),'alternate XML encoding cannot hide a document type declaration');
$line=['amount'=>'1568.00','hours'=>'16.00000000','service_start'=>null,'service_end'=>null];
$explicitCurrency=staffingWorkbookRead($bytes,'synthetic.xlsx',array_replace($selection,['currency_cell'=>'A9']));
$comparison=staffingWorkbookComparison($explicitCurrency,$line,'USD',[],[],['start'=>'2026-10-01','end'=>'2026-10-31']);
$check($comparison['provider_vs_worksheet_amount']['numeric_difference']==='0.00'&&$comparison['provider_vs_worksheet_amount']['monetary_difference']===null,'equal known-currency source values retain unknown provider period');
$check($comparison['worksheet_known_hours_in_common_period']==='16.00'&&$comparison['core_approved_hours_in_common_period']==='0.00'&&$comparison['worksheet_minus_core_hours']==='16.00','missing Core time stays visible as a source-hours discrepancy');
$partial=staffingWorkbookComparison($source,$line,'USD',[],[],['start'=>'2026-10-02','end'=>'2026-10-15']);
$check($partial['worksheet_known_hours_in_common_period']==='8.00'&&$partial['core_comparison_period']===['start'=>'2026-10-02','end'=>'2026-10-15'],'partial-period comparison uses only explicitly overlapping source dates');
$outside=staffingWorkbookComparison($source,$line,'USD',[],[],['start'=>'2026-11-01','end'=>'2026-11-30']);
$check($outside['worksheet_relation_to_selection']==='outside'&&$outside['core_comparison_period']===null&&$outside['worksheet_minus_core_hours']===null,'unrelated selected month cannot produce a Core hour match');
$dated=staffingWorkbookComparison($explicitCurrency,array_replace($line,['service_start'=>'2026-10-01','service_end'=>'2026-10-31']),'USD',[],[],['start'=>'2026-10-01','end'=>'2026-10-31']);
$check($dated['provider_vs_worksheet_amount']['monetary_difference']==='0.00'&&!$dated['time_entry_allocation_proven'],'explicit date-and-currency agreement still does not allocate time entries');
echo "Staffing workbook: $passed passed\n";
